import {STYLE,AXES,generate,preferences,features,fingerprint,cost,fullCost,alternatives,fitAdvice,round,stockInfo,sizeMatches,unitPrice,priceBand,sourcePriceChange,KIND_LABELS} from './engine.js?v=3';
import {renderMannequin,setTextures} from './mannequin.js?v=3';

const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(n), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'<path d="M5 10h10m-4-4 4 4-4 4"/>',up:'<path d="M5 15 15 5M5 5h10v10"/>',heart:'<path d="M17.3 4.5a4.2 4.2 0 0 0-6 0L10 5.8 8.7 4.5a4.2 4.2 0 0 0-6 6L10 18l7.3-7.5a4.2 4.2 0 0 0 0-6Z"/>',refresh:'<path d="M16 7a6.5 6.5 0 1 0 0 6M16 3v4h-4"/>',check:'<path d="m4 10 4 4 8-8"/>',close:'<path d="m5 5 10 10M15 5 5 15"/>',like:'<path d="M6 9h-3v8h3M6 17h8a2 2 0 0 0 2-1.6l1-6A2 2 0 0 0 15 7h-4l1-4c-1-1-2-1-3 1L6 9Z"/>',minus:'<path d="M5 10h10"/>',hanger:'<path d="M8 5a2 2 0 0 1 4 0c0 1.3-2 2-2 3v1M10 9l-8 6c-.8.6-.4 2 1 2h14c1.4 0 1.8-1.4 1-2Z"/>',sun:'<circle cx="10" cy="10" r="3"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M4 4l1 1m10 10 1 1M4 16l1-1m10-10 1-1"/>',leaf:'<path d="M16 3C6 2 2 7 4 12s10 5 12-9ZM4 16l8-8"/>',sliders:'<path d="M4 4h12M4 10h12M4 16h12M7 2v4m6 2v4m-5 2v4"/>',star:'<path d="m10 2 2.2 5 5.4.6-4 3.7 1.1 5.4L10 14l-4.7 2.7 1-5.4-4-3.7 5.5-.6Z"/>',shield:'<path d="m10 2 7 3v5c0 5-7 8-7 8s-7-3-7-8V5Z"/><path d="m7 10 2 2 4-4"/>',plus:'<path d="M10 4v12M4 10h12"/>'};
const icon=k=>`<svg viewBox="0 0 20 20" aria-hidden="true">${icons[k]||icons.arrow}</svg>`;
const labels={top:'Üst',layer:'Katman',bottom:'Alt',shoe:'Ayakkabı'}, families={cream:'Ekru / bej',black:'Siyah',navy:'Lacivert',blue:'Mavi',gray:'Gri',brown:'Kahverengi',olive:'Haki / yeşil',red:'Bordo / kırmızı',purple:'Mor',yellow:'Sarı'};
const defaultState=()=>({version:1,profile:{age:22,height:null,weight:null,fit:'any',chest:null,waist:null,shoe:null,size:'',bottomSize:''},owned:[],custom:[],saved:[],feedback:{},hidden:[],priceNotes:{},seed:1,preview:{mode:'mannequin',build:'regular',layerOpen:true},filters:{budget:3500,weather:'mild',occasion:'day',style:'all',explore:35,availableOnly:true}});
let state=defaultState(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('kendince-v1')||'null');if(raw&&raw.version===1){state={...state,...raw,profile:{...state.profile,...raw.profile},preview:{...state.preview,...raw.preview},filters:{...state.filters,...raw.filters}};for(const k of ['owned','custom','saved','hidden'])if(!Array.isArray(state[k]))state[k]=[];if(!state.feedback||typeof state.feedback!=='object')state.feedback={};if(!state.priceNotes||typeof state.priceNotes!=='object')state.priceNotes={};}}catch{storageOK=false;}
let products=[],catalogDate='',catalogVerifiedAt='',catalogStats={},page='atelier',outfits=[],resultMeta={},activeOutfit=null,alternateProduct=null,wardrobeTab='owned',catalogFilters={query:'',category:'all',kind:'all',sort:'price',brand:'all',stock:'available',min:'',max:'',mySize:false},toastTimer;
const persist=()=>{try{localStorage.setItem('kendince-v1',JSON.stringify(state));}catch{storageOK=false;}};
function toast(msg){const el=$('#toast');el.textContent=msg;el.className='toast';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.className='';el.textContent='';},3200);}
const find=id=>[...products,...state.custom].find(x=>x.id===id), latestPrice=p=>unitPrice(p,state), isOwned=p=>p.custom||state.owned.includes(p.id), sourceDate=p=>state.priceNotes[p.id]?.at(-1)?.date?.slice(0,10)||p.checkedAt;
const formatDate=d=>d?new Date(d.length>10?d:d+'T12:00:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'}):'—';
const formatTime=d=>d?new Date(d).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' TSİ':'—';
function stockBadge(p){const s=stockInfo(p);return `<span class="stock-badge ${s.status==='out_of_stock'?'out':s.status==='unknown'?'unknown':''}">${esc(s.label)}</span>`;}
function stockSummary(p){const s=stockInfo(p);return s.status==='available'?`Beden: ${esc(s.sizes.join(', '))}`:s.status==='out_of_stock'?'Bu renk seçeneğinde stok bulunamadı.':'Güncel beden stoğu kaynakta doğrulanamadı.';}
function sourceHistory(p){return (p.priceHistory?.length?p.priceHistory:[{date:p.checkedAt,price:p.price,source:'previous_snapshot'}]).map(h=>`<div class="history-note"><span>${h.observedAt?formatTime(h.observedAt):formatDate(h.date)} · ${h.source==='product_page'?'Ürün sayfası kontrolü':'Önceki kayıt'}</span><strong>${money(h.price)}</strong></div>`).join('');}
function priceChangeText(p){const c=sourcePriceChange(p);return c?c.delta===0?'Önceki kayıtla aynı':`${c.delta>0?'+':'−'}${money(Math.abs(c.delta))} · ${c.percent>0?'+':''}${c.percent}% önceki kayda göre`:'İlk doğrulanmış gözlem';}
function priceAnalysis(p){const band=priceBand(p,products,state);if(!band)return '<p class="stock-note">Aynı türde fiyat bandı için en az 4 doğrulanmış, stoklu ürün gerekir.</p>';const pct=band.max===band.min?50:Math.max(0,Math.min(100,100*(band.value-band.min)/(band.max-band.min)));return `<div><h3>${esc(band.kind)} fiyat karşılaştırması</h3><p><strong>${esc(band.label)}</strong> · seçkideki ${band.count} stoklu ürünün medyanı ${money(band.median)}. ${band.difference===0?'Medyanla aynı.':`Medyana göre %${Math.abs(band.difference)} ${band.difference<0?'daha düşük':'daha yüksek'}.`}</p><div class="price-track" aria-hidden="true"><i style="left:${pct}%"></i></div><p>${money(band.min)} — ${money(band.max)} · aynı tür, seçtiğin bedene uyan kaynak fiyatları</p><p class="stock-note">Fiyat konumudur; kumaş veya kalite puanı değildir. Kupon ve kargo dahil değil.</p></div>`;}
function renderImage(p,classes='',mini=false){return p.image?`<img class="${classes}" src="${esc(p.image)}" alt="${esc(p.color+' '+p.name)}" loading="lazy">`:`<div class="custom-image ${mini?'mini':''} ${classes}">${icon('hanger')}<span class="swatch tint-${p.family}"></span></div>`;}
function navigate(next){page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function rebuild(){resultMeta=generate(products,state,state.filters);outfits=resultMeta.outfits;}
function updateNav(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#wardrobe-count').textContent=state.owned.length+state.custom.length;}
function render(){updateNav();$('#app').innerHTML=page==='compass'?renderCompass():page==='wardrobe'?renderWardrobe():page==='prices'?renderPrices():renderAtelier();}
function hero(){const p1=find('0212107-91712')||products.find(x=>x.category==='layer'),p2=find('0612731-90892')||products.find(x=>x.category==='top');return `<section class="hero"><div><div class="eyebrow">Tarz bir etiket değil, bir keşif.</div><h1>Kendine yakışanı,<br><em>kendin seç.</em></h1><p>Biraz bildiğin yerden, biraz konfor alanının dışından.<br>Gerçek parçalarla dene, ele, değiştir. Tarzın ortaya çıksın.</p><div class="hero-pills"><span>${icon('check')} Gerçek ürünler</span><span>${icon('sliders')} Senin seçimlerin</span><span>${icon('leaf')} Bütçene göre</span></div></div><div class="hero-art" aria-label="Mavi koleksiyonundan silüet referansları"><div class="hero-shape"></div><img class="hero-photo" src="${p1.image}" alt="Mavi yeşil ekose gömlek silüet referansı"><img class="hero-photo second" src="${p2.image}" alt="Mavi kahverengi tişört silüet referansı"><div class="hero-spark">✳</div><div class="hero-note">Herkes gibi değil.<br>Kendin gibi.<span>İyi bir başlangıç, küçük bir deneme.</span></div><div class="hero-credit">Silüet referansları · Mavi ürün fotoğrafları</div></div></section>`;}
function filters(){const f=state.filters;return `<aside class="filter-panel" aria-label="Kombin tercihleri"><h3>Bugün ne giysek?</h3><p>Çerçeveyi sen çiz.</p><div class="filter-group"><div class="label-row"><label>Nereye?</label></div><div class="segmented">${[['day','Günlük'],['office','Ofis'],['night','Akşam'],['weekend','Hafta sonu']].map(([v,l])=>`<button class="pill ${f.occasion===v?'selected':''}" data-action="occasion" data-value="${v}" aria-pressed="${f.occasion===v}">${l}</button>`).join('')}</div></div><div class="filter-group"><div class="label-row"><label for="budget">Kombin bütçem</label></div><div class="budget-number"><span>₺</span><input id="budget" type="number" min="0" max="100000" step="100" value="${f.budget}" aria-label="Kombin bütçesi, TL"></div><input id="budget-range" type="range" min="500" max="10000" step="100" value="${Math.min(10000,Math.max(500,f.budget))}" aria-label="Bütçe ayarı"><div class="range-labels"><span>₺500</span><span>₺10.000</span></div><p class="filter-note">Bende olanlar bütçeden düşer.<br>Kargo bu hesaba dahil değil.</p></div><div class="filter-group"><div class="label-row"><label for="style-filter">Hangi yoldan?</label></div><select id="style-filter" class="select"><option value="all">Hepsine açığım</option>${Object.entries(STYLE).map(([k,v])=>`<option value="${k}" ${f.style===k?'selected':''}>${v.short}</option>`).join('')}</select><div class="label-row" style="margin:12px 0 7px"><label for="weather">Hava nasıl?</label></div><select id="weather" class="select"><option value="mild" ${f.weather==='mild'?'selected':''}>Ilık · katman isteğe bağlı</option><option value="cool" ${f.weather==='cool'?'selected':''}>Serin · katmanlı kombin</option></select></div><div class="filter-group"><div class="label-row"><label for="explore">Biraz farklılaşalım</label><strong id="explore-value">${f.explore}%</strong></div><input id="explore" type="range" min="0" max="100" step="5" value="${f.explore}" aria-label="Farklı tarzları deneme isteği"><div class="range-labels"><span>Tanıdık</span><span>Yeni bir şey</span></div><p class="filter-note">Yükselttikçe farklı kesim ve vurgu parçaları öne çıkar.</p></div><label class="toggle-row"><input id="available-only" type="checkbox" ${f.availableOnly!==false?'checked':''}><span>Yalnızca fiyatı ve bedeni doğrulanmış stoklu ürünler</span></label><button class="primary" data-action="generate">${icon('refresh')} Kombinleri yenile</button><button class="profile-nudge" data-action="profile"><span>${state.profile.height?'Ölçülerim ve kalıp tercihim':'Ölçülerini ekle, kalıbı konuşalım'}</span>${icon('up')}</button></aside>`;}
function previewControls(inModal=false,hasLayer=true){const v=state.preview;return `<div class="preview-controls ${inModal?'modal-preview-controls':''}"><div class="preview-mode" role="group" aria-label="Kombin görünümü">${!inModal?`<button data-action="preview-mode" data-value="mannequin" aria-pressed="${v.mode==='mannequin'}" class="${v.mode==='mannequin'?'selected':''}">Mankende</button><button data-action="preview-mode" data-value="pieces" aria-pressed="${v.mode==='pieces'}" class="${v.mode==='pieces'?'selected':''}">Parçalar</button>`:'<span>Örnek silüet</span>'}</div><label class="preview-build"><span>Silüet</span><select data-preview-build aria-label="Örnek manken silüeti">${[['slender','İnce'],['regular','Orta'],['broad','Geniş']].map(([k,l])=>`<option value="${k}" ${v.build===k?'selected':''}>${l}</option>`).join('')}</select></label>${hasLayer?`<button class="preview-layer" data-action="preview-layer" aria-pressed="${v.layerOpen!==false}">Katman ${v.layerOpen!==false?'açık':'kapalı'}</button>`:''}</div>`;}
function outfitVisual(o,index,savedView){const saved=state.saved.some(s=>s.fp===fingerprint(o)),mode=state.preview.mode,top=o.items.find(p=>p.category==='top'),bottom=o.items.find(p=>p.category==='bottom'),shoe=o.items.find(p=>p.category==='shoe'),layer=o.items.find(p=>p.category==='layer');return `<div class="outfit-visual visual-${o.style} ${mode==='mannequin'?'has-mannequin':''}"><span class="look-label">${savedView?'Kaydettiğin kombin':index===0?'Başlangıç noktası':index===1?'Başka bir açı':'Küçük bir deneme'}</span><button class="save-button ${saved?'saved':''}" data-action="save" data-id="${esc(o.id)}" aria-label="${saved?'Kayıttan çıkar':'Kombini kaydet'}" aria-pressed="${saved}">${icon('heart')}</button>${mode==='mannequin'?renderMannequin(o,state.preview):renderImage(top,'top-img')+renderImage(bottom,'bottom-img')+renderImage(shoe,'shoe-img')+(layer?renderImage(layer,'layer-img'):'')}<button class="preview-expand" data-action="mannequin" data-id="${esc(o.id)}">Mankende büyüt ${icon('up')}</button></div>`;}
function productStrip(o){return `<div class="preview-product-strip" aria-label="Kombindeki gerçek ürünler">${o.items.map(p=>`<button data-action="product" data-id="${p.id}" aria-label="${esc(p.name)} detayını aç" title="${esc(p.name)}">${renderImage(p)}<span>${labels[p.category]}</span></button>`).join('')}</div>`;}
function mannequinModal(o){activeOutfit=o;showModal(`<div class="modal-wide mannequin-modal">${modalHead(STYLE[o.style].name,'Birlikte nasıl duruyor? Renk, kesim ve katman dengesini tek silüette gör.','Kendince / Mankende')}<div class="mannequin-modal-layout"><section class="mannequin-main">${previewControls(true,o.items.some(p=>p.category==='layer'))}${renderMannequin(o,state.preview)}<p class="preview-explainer">Kumaş dokuları gerçek ürün fotoğraflarından alınır; manken ve kesimler çizimdir. Ölçüye göre prova veya birebir ürün kalıbı göstermez. Fotoğrafı olmayan kendi parçaların renkle temsil edilir.</p></section><section class="mannequin-pieces"><div class="mannequin-summary"><span>BU KOMBİNDE</span><strong>${money(cost(o,state))}</strong><p>Yeni alınacak parçalar · ${o.items.length} parça</p></div>${o.items.map(p=>`<article class="mannequin-item">${renderImage(p)}<div><span>${labels[p.category]} · ${esc(p.brand)}</span><h3>${esc(p.name)}</h3><p>${isOwned(p)?'Bende var · yeni harcama ₺0':money(latestPrice(p))}</p><div class="detail-links"><button data-action="product" data-id="${p.id}">Gerçek fotoğraf</button><button data-action="alternatives" data-id="${p.id}">Değiştir</button></div></div></article>`).join('')}<div class="mannequin-modal-actions"><button class="primary" data-action="detail" data-id="${esc(o.id)}">Parçalar & hesap ${icon('arrow')}</button><button class="outline-button" data-action="save" data-id="${esc(o.id)}">${icon('heart')} Kombini sakla</button></div></section></div></div>`,true);}
function outfitCard(o,index,savedView=false){const t=STYLE[o.style],fp=fingerprint(o),saved=state.saved.some(s=>s.fp===fp),vote=state.feedback[fp];return `<article class="outfit-card">${outfitVisual(o,index,savedView)}${productStrip(o)}<div class="outfit-info"><div class="outfit-kicker"><span>0${index+1} / ${esc(t.short)}</span><span>${o.items.length} parça</span></div><h3>${t.name}</h3><p class="outfit-subtitle">${t.subtitle}</p><div class="swatches">${[...new Set(o.items.map(p=>p.family))].map(k=>`<span class="swatch tint-${k}" title="${families[k]}"></span>`).join('')}<span>${o.items.map(x=>x.brand).filter((x,i,a)=>a.indexOf(x)===i).join(' + ')}</span></div><div class="look-cost"><strong>${money(cost(o,state))}</strong><span>${o.items.some(isOwned)?'eksik parçaların toplamı':'parçaların toplamı'}</span></div><button class="card-details" data-action="detail" data-id="${esc(o.id)}">Parçaları & hesabı gör ${icon('arrow')}</button></div><div class="reaction-row"><button class="${vote?.value===1?'voted':''}" data-action="like" data-id="${esc(o.id)}" aria-pressed="${vote?.value===1}">${icon('like')} Bana yakın</button><button class="${vote?.value===-1?'voted':''}" data-action="dislike" data-id="${esc(o.id)}">${icon('minus')} Bana uzak</button></div></article>`;}
function renderAtelier(){const votes=Object.keys(state.feedback).length;return `${hero()}<div class="section-rule"><h2><span>01</span> Kombin atölyesi</h2><div class="small-muted"><span class="pulse-dot"></span> ${products.length} gerçek ürün · ${catalogStats.stockAvailable||0} stoklu</div></div><div class="atelier-layout">${filters()}<section aria-label="Kombin önerileri"><div class="results-bar"><span class="text">${votes?`<strong>${votes} seçimin</strong> pusulanı şekillendiriyor.`:'Henüz bir tarz etiketi yok. <strong>İlk hissini söyle.</strong>'} <span>${outfits.length} farklı başlangıç.</span></span><button class="text-button" data-action="about">${icon('sliders')} Nasıl seçiliyor?</button></div>${previewControls()}<div class="outfit-grid">${outfits.length?outfits.map((o,i)=>outfitCard(o,i)).join(''):`<div class="empty"><h3>Bu çerçevede henüz kombin yok.</h3><p>${resultMeta.cheapest!==null?`Katalogdaki uygun parçalarla en düşük toplam ${money(resultMeta.cheapest)}. Bütçeyi değiştirebilir veya benzeri sende olan parçaları işaretleyebilirsin.`:(resultMeta.missing?.length?`Şu parçalarda seçtiğin bedene uygun doğrulanmış stok yok: ${resultMeta.missing.map(k=>labels[k]).join(', ')}.`:'Beden, kalıp ve gizlediğin parçaları kontrol et.')}</p><button class="outline-button" data-action="relax">Filtreleri yeniden aç ${icon('refresh')}</button></div>`}</div><div class="tip-strip"><span class="tip-icon">${icon('hanger')}</span><p><strong>İyi kombin, her şeyi satın almak demek değil.</strong><br>Benzeri sende olan parçaları işaretle. Hesap sadece eksiklere kalsın.</p><button data-page="wardrobe">Gardırobuma git ↗</button></div><p class="source-caption">Manken, fotoğraf dokularıyla hazırlanmış bir stil referansıdır. Gerçek ürün kalıbı ve beden için mağaza fotoğraflarını kontrol et. Son kontrol: ${formatTime(catalogVerifiedAt)}. Yalnızca doğrulanan stok ve fiyatlar varsayılan önerilere girer. Satın alırken mağaza bilgisi geçerlidir.</p></section></div><div class="bottom-banner"><div><h3>Tarzını ezberleme. Keşfet.</h3><p>Beğenilerin, elediklerin ve küçük ters köşelerin bir araya gelsin.</p></div><button class="outline-button" data-page="compass">Tarz pusulam ${icon('up')}</button></div>`;}
function renderCompass(){
 const pref=preferences(state), votes=Object.values(state.feedback), likes=votes.filter(v=>v.value>0), saved=state.saved.map(savedOutfit).filter(Boolean);
 const directions=AXES.slice().sort((a,b)=>pref[b[0]]-pref[a[0]]).slice(0,2).map(x=>x[1].toLocaleLowerCase('tr')).join(' ve ');
 const axes=AXES.map(([k,l])=>`<div class="axis"><span>${l}</span><span class="track"><i style="width:${pref[k]}%"></i></span><span>${pref[k]}</span></div>`).join('');
 const history=votes.slice(-6).reverse().map(v=>{const p=find(v.items[0]);const reason=({color:'Rengi',fit:'Kesimi',pattern:'Deseni',overall:'Genel havası'})[v.reason]||'Genel havası';return `<div class="vote-mini">${p?renderImage(p):''}<div><strong>${v.value>0?'Bana yakın':'Bana uzak'}</strong><p>${STYLE[v.style]?.short||'Kombin'} · ${reason}</p></div></div>`;}).join('');
 const note=votes.length<5?'İlk 5–10 seçimden sonra eğilimler daha anlaşılır olur. Sevmediğin bir rengin bütün tarzını elemesine gerek yok.':`Şu an ${directions} tarafı öne çıkıyor. Yeni denemeler yaptıkça bu da değişebilir.`;
 return `<div class="page-heading"><div class="eyebrow">Seçtiklerin bir şey anlatıyor.</div><h1>Tarz pusulam</h1><p>Bir kutuya girmek zorunda değilsin. Neye yaklaştığını, neyi elediğini ve nerede yeni bir şey denemek istediğini gör.</p></div>
 <div class="compass-layout"><section class="panel"><h2>${votes.length?'Senin yönlerin':'Önce biraz deneyelim.'}</h2><p>${votes.length?'Bu çubuklar seçimlerinin bir özeti. Bir kişilik testi veya bilimsel uyum yüzdesi değil.':'Pusula şimdilik ortada. Kombinlere “bana yakın” veya “bana uzak” diyerek ilk izleri bırak.'}</p>${axes}<div class="note-box">${note}</div></section>
 <section class="panel"><h2>Kararlarının izi</h2><div class="stats"><div class="stat"><strong>${votes.length}</strong><span>değerlendirme</span></div><div class="stat"><strong>${likes.length}</strong><span>bana yakın</span></div><div class="stat"><strong>${state.saved.length}</strong><span>kayıtlı kombin</span></div></div><p>“Bana uzak” dediğinde nedenini seçebilirsin. Renk, kesim ve desen ayrı ayrı pusulanı etkiler. “Genel havası” bütün yönleri etkiler.</p><div class="note-box">Tanıdık olanla yeni olan arasındaki dengeyi atölyedeki “Biraz farklılaşalım” ayarıyla sen kurarsın. Beğenilerin değişebilir.</div><div style="margin-top:22px;display:flex;gap:18px;align-items:center"><button class="primary" data-page="atelier">Yeni bir deneme ${icon('arrow')}</button>${votes.length?'<button class="text-button" data-action="reset-taste">Pusulayı sıfırla</button>':''}</div></section></div>
 <h2 class="subsection-title">Son değerlendirmelerin</h2>${votes.length?`<div class="vote-history">${history}</div>`:'<div class="method-note">Henüz değerlendirme yok. Atölyede üç başlangıç seni bekliyor.</div>'}
 <h2 class="subsection-title">Tekrar bakmak istediklerin</h2>${saved.length?`<div class="outfit-grid saved-grid">${saved.map((o,i)=>outfitCard(o,i,true)).join('')}</div>`:`<div class="empty"><h3>Bir kombini kalple sakla.</h3><p>Karar vermeden önce birkaç kez bakmak serbest.</p><button class="outline-button" data-page="atelier">Atölyeye dön ${icon('arrow')}</button></div>`}`;
}
function savedOutfit(s){const items=s.items.map(find).filter(Boolean);return items.length>=3?{id:s.fp+'::'+s.style,fp:s.fp,style:s.style,items,features:features({items})}:null;}
function renderWardrobe(){const own=[...products.filter(p=>state.owned.includes(p.id)),...state.custom],hidden=products.filter(p=>state.hidden.includes(p.id)),list=wardrobeTab==='hidden'?hidden:own;return `<div class="page-heading"><div class="eyebrow">Önce sende olana bak.</div><div class="heading-flex"><h1>Gardırobum</h1><button class="outline-button" data-action="custom">${icon('plus')} Parça ekle</button></div><p>Benzeri sende olan parçalar alışveriş bütçenden düşer. Kendi parçanı da ekleyebilirsin; uygun renk ve kategoriyle kombinlere katılır.</p></div><div class="tabs"><button class="${wardrobeTab==='owned'?'selected':''}" data-action="wardrobe-tab" data-value="owned">Bende olanlar (${own.length})</button><button class="${wardrobeTab==='hidden'?'selected':''}" data-action="wardrobe-tab" data-value="hidden">Gizlediğim ürünler (${hidden.length})</button></div>${list.length?`<div class="product-grid">${list.map(p=>`<article class="product-card">${renderImage(p)}<div class="product-body"><span class="badge">${p.custom?'Kendi parçam':wardrobeTab==='hidden'?'Önerilere dahil değil':'Bende benzeri var'}</span><h3 style="margin-top:10px">${esc(p.name)}</h3><p>${esc(p.color||families[p.family])} · ${labels[p.category]} · ${esc(p.fitLabel||p.fit)}</p><button data-action="${wardrobeTab==='hidden'?'unhide':p.custom?'remove-custom':'unown'}" data-id="${p.id}">${wardrobeTab==='hidden'?'Önerilere geri ekle':'Gardırobumdan çıkar'}</button></div></article>`).join('')}</div>`:`<div class="empty"><h3>${wardrobeTab==='hidden'?'Gizlediğin ürün yok.':'Gardırobunla başlayalım.'}</h3><p>${wardrobeTab==='hidden'?'Bir ürünün detayında “Önerilerde gösterme” seçebilirsin.':'Kombin detayındaki “Bende benzeri var” seçeneğini işaretle veya kendi parçanı ekle.'}</p><button class="primary" data-action="custom">${icon('plus')} İlk parçamı ekle</button></div>`}<div class="bottom-banner"><div><h3>Daha az alışveriş, daha çok kombin.</h3><p>${own.length?`${own.length} parçan artık kombin hesabına dahil.`:'Önce bir tişört, bir pantolon, bir ayakkabı ekleyebilirsin.'}</p></div><button class="outline-button" data-page="atelier">Yeniden kombinle ${icon('arrow')}</button></div>`;}
function catalogList(){let a=products.filter(p=>{
 const f=catalogFilters,s=stockInfo(p),v=latestPrice(p);
 return(f.category==='all'||p.category===f.category)&&(f.kind==='all'||p.kind===f.kind)&&(f.brand==='all'||p.brand===f.brand)&&(f.stock==='all'||f.stock==='unverified'&&p.priceStatus!=='verified'||s.status===f.stock)&&(!f.mySize||sizeMatches(p,state.profile))&&(f.min===''||v>=Number(f.min))&&(f.max===''||v<=Number(f.max))&&`${p.name} ${p.color} ${p.brand} ${p.seller||''} ${KIND_LABELS[p.kind]||''}`.toLocaleLowerCase('tr').includes(f.query.toLocaleLowerCase('tr'));
 });return a.sort((a,b)=>catalogFilters.sort==='high'?latestPrice(b)-latestPrice(a):catalogFilters.sort==='band'?(priceBand(a,products,state)?.difference??999)-(priceBand(b,products,state)?.difference??999):latestPrice(a)-latestPrice(b));}
function priceRows(list){return list.map(p=>{const b=priceBand(p,products,state),manual=state.priceNotes[p.id]?.length;return `<tr><td><div class="table-product">${renderImage(p)}<div><button class="table-product-name" data-action="product" data-id="${p.id}">${esc(p.name)}</button><span>${esc(p.brand)} · ${esc(p.color)} · ${KIND_LABELS[p.kind]||labels[p.category]}</span><div class="catalog-status">${stockBadge(p)}</div><p class="stock-note">${stockSummary(p)}</p></div></div></td><td><strong>${money(latestPrice(p))}</strong><span class="price-date">${manual?'Senin fiyat notun':p.priceStatus==='verified'?'Kaynakta doğrulandı':'Yeniden doğrulanmadı'}</span>${b?`<span class="price-position ${b.position}">${b.label}<br>Medyan ${money(b.median)} · ${b.count} ürün</span>`:''}</td><td><span class="price-date">${p.verifiedAt?formatTime(p.verifiedAt):formatDate(p.checkedAt)+' · eski kayıt'}</span><p class="stock-note">${p.priceStatus==='verified'?priceChangeText(p):'Bu turda kaynağa erişilemedi.'}</p><button data-action="price-note" data-id="${p.id}">Fiyat not et ↗</button></td><td><button data-action="own-toggle" data-id="${p.id}">${isOwned(p)?'✓ Bende var':'+ Bende benzeri var'}</button></td><td><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(p.name)} mağaza sayfasını aç">Mağazada gör ↗</a>${p.seller?`<p class="stock-note">Satıcı: ${esc(p.seller)}</p>`:''}</td></tr>`;}).join('')||'<tr><td colspan="5">Bu filtrelerde ürün yok. Beden, fiyat veya stok seçimini değiştirebilirsin.</td></tr>';}
function refreshCatalogRows(){const list=catalogList();$('#price-rows').innerHTML=priceRows(list);$('#catalog-count').textContent=list.length+' ürün gösteriliyor';}
function categoryAnalysis(){return Object.entries(labels).map(([cat,label])=>{const list=products.filter(p=>p.category===cat&&p.priceStatus==='verified'&&stockInfo(p).status==='available'),base={...state,priceNotes:{},profile:{}},values=list.map(p=>unitPrice(p,base)).sort((a,b)=>a-b),mid=values.length?round((values[Math.floor((values.length-1)/2)]+values[Math.ceil((values.length-1)/2)])/2):null;return `<div class="analysis-card"><h3>${label} · ${list.length} stoklu ürün</h3><strong>${mid===null?'—':money(mid)}</strong><p>Kategori medyanı${values.length?`<br>${money(values[0])} — ${money(values.at(-1))}`:''}</p></div>`;}).join('');}
function renderPrices(){const f=catalogFilters,stats=catalogStats,list=catalogList(),brands=[...new Set(products.map(p=>p.brand))].sort((a,b)=>a.localeCompare(b,'tr')),kinds=[...new Set(products.map(p=>p.kind))];return `<div class="page-heading"><div class="eyebrow">Hesabı açık tutalım.</div><h1>Fiyat masası</h1><p>Stoklu bedeni bul, benzer parçaların fiyat bandını gör. Etiketteki büyük indirim yerine gerçek fiyatın seçkide nereye düştüğüne bak.</p></div><div class="price-stats"><div class="price-stat"><span>KATALOG</span><strong>${products.length} ürün</strong><p>${brands.length} marka / seri · LCW ve Mavi kaynakları</p></div><div class="price-stat"><span>FİYATI DOĞRULANAN</span><strong>${stats.priceVerified||0} ürün</strong><p>${stats.notReverified||0} eski kayıt ayrıca işaretli</p></div><div class="price-stat"><span>STOKLU BEDENİ GÖRÜLEN</span><strong>${stats.stockAvailable||0} ürün</strong><p>${stats.stockOut||0} tükenmiş · ${stats.stockUnknown||0} stok doğrulanamadı</p></div></div><div class="verification-note"><strong>Son kontrol: ${formatTime(catalogVerifiedAt)}.</strong> Ürün sayfasındaki fiyat ve bu renk seçeneğinin beden adetleri kontrol edildi. Stok bir anlık kayıt; satın alırken mağaza bilgisi geçerlidir. Mavi'deki ${stats.notReverified||0} eski kayıt bu turda yeniden doğrulanamadı ve varsayılan kombinlerden çıkarıldı. <a href="catalog-audit.json" target="_blank" rel="noopener">Kontrol dökümü ↗</a></div><div class="analysis-grid">${categoryAnalysis()}</div><p class="price-disclosure">Kategori kartları geniş grupların özetidir. Ürünlerin fiyat bandı ise aynı parça türündeki (örneğin jean veya tişört) en az 4 doğrulanmış, stoklu ürünle hesaplanır. Medyan, sıralanmış fiyatların ortanca değeridir. Kalite veya piyasanın tamamı hakkında puan değildir.</p><div class="catalog-tools"><input id="catalog-search" class="search-input" type="search" placeholder="Ürün, renk, marka veya satıcı ara…" value="${esc(f.query)}" aria-label="Katalogda ara"><select id="catalog-category" class="select" aria-label="Kategori"><option value="all">Bütün parçalar</option>${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${f.category===k?'selected':''}>${l}</option>`).join('')}</select><select id="catalog-kind" class="select" aria-label="Parça türü"><option value="all">Bütün türler</option>${kinds.map(k=>`<option value="${k}" ${f.kind===k?'selected':''}>${esc(KIND_LABELS[k]||k)}</option>`).join('')}</select><select id="catalog-brand" class="select" aria-label="Marka veya seri"><option value="all">Bütün markalar / seriler</option>${brands.map(k=>`<option value="${esc(k)}" ${f.brand===k?'selected':''}>${esc(k)}</option>`).join('')}</select><select id="catalog-sort" class="select" aria-label="Sıralama"><option value="price" ${f.sort==='price'?'selected':''}>Fiyat: düşük → yüksek</option><option value="high" ${f.sort==='high'?'selected':''}>Fiyat: yüksek → düşük</option><option value="band" ${f.sort==='band'?'selected':''}>Tür medyanına göre düşük</option></select></div><div class="price-tools-more"><div class="field"><label for="catalog-stock">Stok durumu</label><select id="catalog-stock"><option value="available" ${f.stock==='available'?'selected':''}>Stoklu beden görüldü</option><option value="all" ${f.stock==='all'?'selected':''}>Bütün kayıtlar</option><option value="out_of_stock" ${f.stock==='out_of_stock'?'selected':''}>Tükenmiş ürünler</option><option value="unknown" ${f.stock==='unknown'?'selected':''}>Stok doğrulanamadı</option><option value="unverified" ${f.stock==='unverified'?'selected':''}>Eski fiyat kayıtları</option></select></div><div class="field"><label for="catalog-min">En az (TL)</label><input id="catalog-min" type="number" min="0" step="50" value="${esc(f.min)}" placeholder="0"></div><div class="field"><label for="catalog-max">En çok (TL)</label><input id="catalog-max" type="number" min="0" step="50" value="${esc(f.max)}" placeholder="Sınır yok"></div><label class="toggle-row"><input id="catalog-my-size" type="checkbox" ${f.mySize?'checked':''}>Profilimdeki bedene uyanlar</label><button class="text-button" data-action="profile">Bedenimi düzenle ↗</button></div><p id="catalog-count" class="small-muted" style="margin:0 0 12px">${list.length} ürün gösteriliyor</p><div class="table-wrap"><table class="price-table"><thead><tr><th>Parça / beden stoğu</th><th>Fiyat / konumu</th><th>Kontrol / geçmiş</th><th>Gardırobum</th><th>Kaynak</th></tr></thead><tbody id="price-rows">${priceRows(list)}</tbody></table></div><p class="price-disclosure">Fiyatlar TRY ve ürün başınadır. Bedene göre değişen fiyatlarda seçimine uyan stoklu bedenlerin en yüksek fiyatı hesapta kullanılır. Kargo, kupon ve sepet kampanyaları dahil değil. Karşılaştırma farklı ürünlerden oluşur; aynı ürünü bütün satıcılarda arayıp en ucuzunu bulma iddiası taşımaz. Otomatik canlı tarama yok. Fiyat notların kaynak medyanını değiştirmez.</p>`;}
const modalHead=(title,sub='',eyebrow='Kendince / Atölye')=>`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="close-modal" data-action="close" aria-label="Kapat">${icon('close')}</button></div>`;
function showModal(html,wide=false){const d=$('#modal');d.classList.toggle('wide',wide);$('#modal-content').innerHTML=html;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
function profileModal(){const p=state.profile;showModal(`<div class="modal">${modalHead('Ölçü, kalıp, rahatlık.','Bedenin bir tarz etiketi değil. Bu bilgiler sadece başlangıç rehberi.')}<form id="profile-form"><div class="form-grid"><div class="field"><label for="age">Yaş</label><input id="age" name="age" type="number" min="16" max="100" value="${p.age??''}" required><small>Yaş, tarz seçeneklerini kısıtlamaz.</small></div><div class="field"><label for="height">Boy (cm)</label><input id="height" name="height" type="number" min="130" max="220" step="1" value="${p.height??''}" placeholder="Örn. 178"></div><div class="field"><label for="weight">Kilo (kg)</label><input id="weight" name="weight" type="number" min="35" max="250" step="0.1" value="${p.weight??''}" placeholder="Örn. 75"></div><div class="field"><label for="fit">Kalıp tercihim</label><select id="fit" name="fit">${[['any','Denemeye açığım'],['regular','Regular / düz'],['wide','Rahat / bol'],['slim','Dar / slim']].map(([k,l])=>`<option value="${k}" ${p.fit===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="chest">Göğüs çevresi (cm) · isteğe bağlı</label><input id="chest" name="chest" type="number" min="60" max="180" value="${p.chest??''}" placeholder="En geniş yerden"></div><div class="field"><label for="waist">Bel çevresi (cm) · isteğe bağlı</label><input id="waist" name="waist" type="number" min="50" max="180" value="${p.waist??''}" placeholder="Vücut ölçüsü"></div><div class="field"><label for="shoe">Ayakkabı numaram · isteğe bağlı</label><input id="shoe" name="shoe" type="number" min="35" max="50" step="0.5" value="${p.shoe??''}" placeholder="EU"></div><div class="field"><label for="size">Üst bedenim · biliyorsam</label><select id="size" name="size"><option value="">Beden filtresi kullanma</option>${['XS','S','M','L','XL','XXL','XXXL'].map(s=>`<option ${p.size===s?'selected':''}>${s}</option>`).join('')}</select><small>Stoklu üstleri bu bedenle filtreler.</small></div><div class="field"><label for="bottom-size">Pantolon bedenim · biliyorsam</label><input id="bottom-size" name="bottomSize" value="${esc(p.bottomSize)}" placeholder="Örn. 32, 32/32 veya M" maxlength="12"><small>Etiketteki bedeni gir. 32, tüm 32 bel seçeneklerini gösterir; iç bacak boyunu ayrıca kontrol et.</small></div></div><button class="primary" type="submit">Ölçülerimi kaydet ${icon('check')}</button><p class="form-foot">${storageOK?'Bilgilerin bu tarayıcıda saklanır.':'Kalıcı kayıt şu an kullanılamıyor; bilgiler bu oturumda tutulur.'} Her zaman değiştirebilirsin.</p></form>${p.height?`<div class="profile-guide"><h3>Başlangıç kalıp rehberin</h3><ul>${fitAdvice(p).map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}</div>`);}
function getOutfit(id){return outfits.find(o=>o.id===id)||state.saved.map(savedOutfit).find(o=>o?.id===id)||activeOutfit?.id===id&&activeOutfit;}
function explain(o){const p=o.items.filter(p=>p.category!=='shoe'),accent=p.find(p=>['red','purple','yellow'].includes(p.family)),names=[...new Set(p.map(x=>families[x.family]))];let a=[`${names.join(', ')} tonları ${accent?'bir vurgu parçası çevresinde':'dengeli bir palet içinde'} bir araya geldi.`,p.some(p=>p.fit==='wide')?'Bol parçaya hareket alanı verdik; paça ve üst boyunu birlikte kontrol et.':'Regular ve düz kesimler daha kontrollü bir silüet kuruyor.',o.items.some(isOwned)?'Sende olan benzer parçalar alışveriş hesabından çıkarıldı.':'Bu bir satın alma listesi olmak zorunda değil; benzer parçaları gardırobunda ara.'];if(state.profile.fit!=='any')a.push('Kalıp tercihin sıralamaya dahil edildi.');return a;}
function budgetSwap(o){const candidates=o.items.filter(p=>!isOwned(p)).flatMap(p=>alternatives(p,o,products,state,state.filters.budget).filter(a=>a.delta>0).map(a=>({...a,original:p}))).sort((a,b)=>b.delta-a.delta),best=candidates[0];return best?`<div class="budget-swap"><h4>Hesabı hafiflet</h4><p>${labels[best.original.category]} parçasını ${esc(best.product.brand)} · ${esc(best.product.name)} ile değiştirirsen <strong>${money(best.delta)} daha az</strong> harcama. Yeni toplam ${money(best.cost)}.</p><button data-action="alternatives" data-id="${best.original.id}">Alternatifleri karşılaştır ↗</button><p class="stock-note">Farklı ürünler; aynı kalite iddiası yok.</p></div>`:'';}
function detailModal(o){activeOutfit=o;const spend=cost(o,state),total=fullCost(o,state),owned=round(total-spend),cats=o.items.map(p=>({p,v:isOwned(p)?0:latestPrice(p)}));showModal(`<div class="modal-wide">${modalHead(STYLE[o.style].name,'Parçayı değiştirebilir, benzerini gardırobundan kullanabilirsin.',STYLE[o.style].short)}<div class="detail-layout"><div class="detail-products">${o.items.map(p=>`<article class="detail-product">${renderImage(p,'',true)}<div class="product-text"><h3>${esc(p.name)}</h3><p>${p.brand} · ${esc(p.color||families[p.family])} · ${esc(p.fitLabel||p.fit)}</p><div class="product-price">${isOwned(p)?'<span class="owned-label">Bende var · yeni harcama ₺0</span>':money(latestPrice(p))}${state.priceNotes[p.id]?.length?' <span class="price-date">(not ettiğin fiyat)</span>':''}</div>${!p.custom?`<div class="catalog-status">${stockBadge(p)}</div><p class="stock-note">${stockSummary(p)}</p>`:''}<div class="detail-links">${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Mağazada gör ↗</a>`:''}<button data-action="alternatives" data-id="${p.id}">Parçayı değiştir</button><button data-action="product" data-id="${p.id}">Detay</button></div>${!p.custom?`<label class="own-check"><input type="checkbox" data-own="${p.id}" ${isOwned(p)?'checked':''}> Bende benzeri var</label>`:''}</div></article>`).join('')}<p class="source-caption">Mağaza fotoğrafları ürünün kendi görselleridir. Fotoğraftaki diğer giysiler bu kombin listesine dahil değildir.</p></div><div class="detail-side"><div class="detail-total"><span>YENİ ALINACAK PARÇALAR</span><strong>${money(spend)}</strong><p>${owned>0?`Sende olanların katalog karşılığı ${money(owned)} düştü.<br>`:''}Kombinin katalog toplamı: ${money(total)}<br>Kargo ve kupon dahil değil.</p></div><div class="cost-bar">${cats.map((x,i)=>`<span style="flex:${x.v||0.01};background:${['#577954','#91a17b','#b7c394','#d1d5b4'][i%4]}"></span>`).join('')}</div>${cats.map(x=>`<div class="cost-breakdown"><span>${labels[x.p.category]}</span><span>${money(x.v)}</span></div>`).join('')}${budgetSwap(o)}<div class="detail-note"><h3>Neden birlikte?</h3><ul>${explain(o).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail-note"><h3>Giymeden önce</h3><p>${esc(fitAdvice(state.profile)[0])}</p><p style="margin-top:7px">${state.filters.weather==='cool'?'Katmanlı geçiş önerisi; soğuk kış havası için sıcaklık garantisi vermez.':'Ilık hava başlangıcı; hava durumunu ayrıca kontrol et.'}</p></div><div class="detail-note"><h3>Bir de kullanım hesabı</h3><p>Bu kombin için <input id="wears" type="number" value="30" min="1" max="1000" style="width:47px;padding:2px 5px;border:1px solid #d4ddc9;border-radius:3px" aria-label="Planlanan giyme sayısı"> giyme planlarsan yeni harcama <strong id="cost-per-wear">${money(round(spend/30))}</strong> / giyme.<br>Bu sayı senin varsayımın; dayanıklılık tahmini değil.</p></div></div></div><div class="detail-footer"><button class="outline-button" data-action="mannequin" data-id="${esc(o.id)}">Mankende gör ${icon('up')}</button><button class="primary" data-action="save" data-id="${esc(o.id)}">${icon('heart')} ${state.saved.some(s=>s.fp===fingerprint(o))?'Kaydı kaldır':'Kombini sakla'}</button><button class="outline-button" data-action="like" data-id="${esc(o.id)}">${icon('like')} Bana yakın</button><button class="text-button" data-action="dislike" data-id="${esc(o.id)}">Bana uzak</button></div><p class="source-caption">Son kaynak kontrolü ${formatTime(catalogVerifiedAt)}. Eski kayıtlar ve not ettiğin fiyatlar ayrıca işaretlenir. Satın almadan önce beden ve stok kontrol et.</p></div>`,true);}
function alternativeModal(id){alternateProduct=find(id);const list=alternatives(alternateProduct,activeOutfit,products,state,state.filters.budget);showModal(`<div class="modal">${modalHead('Bir parçayı değiştir.','Aynı kategoride renk, kalıp ve bütçe kurallarına uyan alternatifler.')}<p class="small-muted" style="margin-bottom:18px">Değişen: ${esc(alternateProduct.name)} · ${money(latestPrice(alternateProduct))}</p>${list.slice(0,12).map(a=>`<div class="alternate-row">${renderImage(a.product,'',true)}<div><h3>${esc(a.product.name)}</h3><p>${a.product.brand} · ${esc(a.product.color||families[a.product.family])} · ${a.product.custom?'Sende var':money(latestPrice(a.product))}</p>${!a.product.custom?stockBadge(a.product):''}<p>${a.delta>0?`${money(a.delta)} daha az harcama`:a.delta<0?`${money(-a.delta)} ek harcama`:'Hesap aynı'} · Yeni toplam ${money(a.cost)}</p></div><button data-action="swap" data-id="${a.product.id}">Seç</button></div>`).join('')||'<div class="detail-empty">Bu bütçede uyumlu alternatif yok. Atölyeden bütçeyi değiştirebilir veya kendi parçanı ekleyebilirsin.</div>'}<button class="outline-button" data-action="back-detail">${icon('arrow')} Kombine geri dön</button><p class="source-caption">Alternatifler farklı ürünlerdir. Fiyat farkı kalite veya aynı ürün karşılaştırması değildir.</p></div>`);}
function productModal(p){const s=stockInfo(p);showModal(`<div class="modal">${modalHead(esc(p.name),`${esc(p.brand)} · ${esc(p.color||families[p.family])}`)}${p.image?`<img src="${esc(p.alternateImage||p.image)}" alt="${esc(p.name)}" style="width:100%;max-height:340px;object-fit:contain;background:#f7f7f0;border-radius:5px;margin-bottom:18px">`:''}<div class="about-list"><div><h3>${money(latestPrice(p))} ${p.custom?'· Gardırobundaki parça':''}</h3><p>${p.custom?'Yeni harcama ₺0.':`${state.priceNotes[p.id]?.length?'Senin son fiyat notun':p.priceStatus==='verified'?'Kaynakta doğrulanan fiyat':'Yeniden doğrulanmamış eski fiyat'} · ${state.priceNotes[p.id]?.length?formatDate(sourceDate(p)):p.verifiedAt?formatTime(p.verifiedAt):formatDate(p.checkedAt)}`}</p>${!p.custom?`<div class="catalog-status">${stockBadge(p)}</div><p class="stock-note">${stockSummary(p)}</p>`:''}</div><div><h3>Kalıp ve kumaş</h3><p>${esc(p.fitLabel||p.fit)} · ${esc(p.material||'Kumaş belirtilmedi')}<br>${esc(p.description)}</p></div>${!p.custom&&s.status!=='unknown'&&p.sizes?.length?`<div><h3>Beden bazında kaynak stoğu</h3><p>${formatTime(p.stock?.checkedAt)} · üstü çizili bedenlerde adet sıfır.</p><div class="size-chip-list">${p.sizes.map(v=>`<span class="size-chip ${v.available?'':'unavailable'}" title="${v.available?'Kaynakta stok var':'Kaynakta stok yok'}">${esc(v.size)}${v.available&&v.price&&v.price!==p.price?` · ${money(v.price)}`:''}</span>`).join('')}</div><p class="stock-note">Bu liste canlı değil. Beden, renk ve güncel fiyatı mağazada tekrar kontrol et.</p></div>`:!p.custom?'<div><h3>Beden stoğu belirsiz</h3><p>Eski beden listesi güncel stok olarak gösterilmez. Varsayılan kombin seçimine dahil değil; mağazada kontrol et.</p></div>':''}${!p.custom?priceAnalysis(p):''}${!p.custom?`<div><h3>Kaynak fiyatının izi</h3><p>${p.priceStatus==='verified'?priceChangeText(p):'Bu turda yeniden doğrulanamadı.'}</p>${sourceHistory(p)}<p class="stock-note">Geçmiş yalnızca kaydedilen gözlemlerden oluşur; günlük takip veya en düşük tarihsel fiyat iddiası yok.</p><button class="text-button" data-action="price-note" data-id="${p.id}">Kendi fiyat gözlemimi ekle ↗</button></div>`:''}${p.url?`<div><a class="outline-button" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Kaynak ürün sayfası ${icon('up')}</a>${p.seller?`<p class="stock-note">Satıcı: ${esc(p.seller)}</p>`:''}</div>`:''}</div><div style="margin-top:20px;display:flex;gap:15px">${activeOutfit?'<button class="text-button" data-action="back-detail">Kombine dön</button>':''}${!p.custom?`<button class="text-button" data-action="hide" data-id="${p.id}">Önerilerde gösterme</button>`:''}</div></div>`);}
function dislikeModal(o){activeOutfit=o;showModal(`<div class="modal">${modalHead('Neresi sana uzak?','Bir kombini elemek, bütün tarzı elemek değil.')}<div class="rejection-options">${[['color','Renkleri','Bu palet bana göre değil.'],['fit','Kesimi','Bu silüette rahat hissetmem.'],['pattern','Desen / baskı','Daha sade bir şey arıyorum.'],['overall','Genel havası','Parçalar birlikte bana uzak.']].map(([k,t,d])=>`<button data-action="reject" data-value="${k}">${t}<small>${d}</small></button>`).join('')}</div><p class="form-foot">Bu geri bildirim pusulanı etkiler. Aynı kombini yeniden zorlamayız.</p></div>`);}
function addCustomModal(){showModal(`<div class="modal">${modalHead('Sende olan bir parça.','Fotoğraf şart değil. Renk, kategori ve kesimle kombinlere katılsın.')}<form id="custom-form"><div class="form-grid"><div class="field span-2"><label for="custom-name">Parçanın adı</label><input id="custom-name" name="name" maxlength="70" required placeholder="Örn. her gün giydiğim beyaz tişört"></div><div class="field"><label for="custom-category">Kategori</label><select id="custom-category" name="category">${Object.entries(labels).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div><div class="field"><label for="custom-color">Renk</label><select id="custom-color" name="family">${Object.entries(families).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div><div class="field"><label for="custom-fit">Kesim</label><select id="custom-fit" name="fit"><option value="regular">Regular / düz</option><option value="wide">Rahat / bol</option><option value="slim">Dar / slim</option></select></div><div class="field"><label for="custom-formality">Genel hava</label><select id="custom-formality" name="formality"><option value="1">Sade günlük</option><option value="0">Spor / sokak</option><option value="2">Daha özenli</option></select></div><div class="field"><label for="custom-pattern">Desen</label><select id="custom-pattern" name="pattern"><option value="plain">Düz / desensiz</option><option value="patterned">Desenli / baskılı</option></select></div><div class="field"><label for="custom-warmth">Kumaş hissi</label><select id="custom-warmth" name="warmth"><option value="1">İnce / hafif</option><option value="2">Daha kalın / katman</option></select></div></div><button class="primary" type="submit">Gardırobuma ekle ${icon('plus')}</button><p class="form-foot">Bu parçanın yeni harcaması ₺0. Katalog görseli olmayan parçalar simgeyle görünür.</p></form></div>`);}
function priceNoteModal(p){const notes=state.priceNotes[p.id]||[];showModal(`<div class="modal">${modalHead('Fiyatını not et.',esc(p.name))}<div class="note-box">${p.priceStatus==='verified'?'Kaynakta doğrulanan fiyat':'Yeniden doğrulanmamış eski fiyat'}: ${money(p.price)} · ${p.verifiedAt?formatTime(p.verifiedAt):formatDate(p.checkedAt)}<br>Mağazada gördüğün yeni fiyatı gir. Bu bir manuel gözlem olarak kaydolur.</div><form id="price-note-form" data-id="${p.id}" style="margin-top:22px"><div class="field"><label for="price-note">Yeni gözlem (TL)</label><input id="price-note" name="price" type="number" min="1" max="100000" step="0.01" value="${latestPrice(p)}" required></div><button class="primary" type="submit">Fiyat notumu kaydet ${icon('check')}</button></form><div class="price-history"><h3 style="font-family:var(--serif);font-size:20px;font-weight:400;margin-bottom:10px">Kayıtlı gözlemler</h3>${sourceHistory(p)}${notes.map(n=>`<div class="history-note"><span>${formatDate(n.date.slice(0,10))} · Senin notun</span><strong>${money(n.price)}</strong></div>`).join('')}${notes.length?`<button class="text-button" data-action="clear-price" data-id="${p.id}">Notlarımı kaldır, kaynak fiyatına dön</button>`:''}</div>${p.url?`<a class="outline-button" style="margin-top:18px" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Mağazada kontrol et ${icon('up')}</a>`:''}</div>`);}
function aboutModal(){showModal(`<div class="modal">${modalHead('Kombin nasıl seçiliyor?','Senin seçimlerin ve açık kurallar.')}<div class="about-list"><div><h3>01 / Önce çerçeve</h3><p>Bütçe, kullanım yeri, hava ve kalıp tercihin adayları belirler. Varsayılan seçim yalnızca fiyatı doğrulanmış ve seçtiğin bedende stok görülen ürünleri kullanır. Sende olan parçalarda satın alma stoğu aranmaz. Boy ve kilo kalıp rehberine katkı sağlar; yaştan bir giyim etiketi çıkarılmaz.</p></div><div><h3>02 / Birlikte duran parçalar</h3><p>Renk aileleri, kesim ve parçanın gündelik veya özenli havası birlikte değerlendirilir. Birden çok güçlü vurgu rengini ve üst üste desenleri sınırlayan basit kurallar kullanılır.</p></div><div><h3>03 / Seçimlerinden bir pusula</h3><p>Beğenilerin beş yönün ağırlığını değiştirir. Beğenmediğinde renk, kesim ve desen ayrı etkilenebilir. Keşif ayarı daha farklı denemelere alan açar. AI, sohbet modeli veya dışarıya gönderilen kişisel veri yok.</p></div><div><h3>04 / Gerçek fiyat, açık sınır</h3><p>${products.length} ürünün sayfası ve fotoğrafı var. ${catalogStats.priceVerified||0} fiyat ve ${catalogStats.stockAvailable||0} stoklu ürün, ${formatTime(catalogVerifiedAt)} kontrolünde doğrulandı. ${catalogStats.notReverified||0} eski fiyat yeniden doğrulanamadı. Otomatik canlı tarama yok. Fiyat bandı, aynı türdeki doğrulanmış stoklu ürünlerin kaynak fiyatlarından hesaplanır. Alternatifler aynı ürünün satıcı karşılaştırması değildir. Kargo ve sepet kampanyaları dahil değil. Beden ve stok mağazada doğrulanmalı.</p></div><div><h3>05 / Kayıtların sende</h3><p>Profilin, gardırobun, beğenilerin ve fiyat notların bu tarayıcıda saklanır. Cihazlar arasında eşitlenmez. “Verilerimi indir” ile yedek alabilirsin. Gerçek fotoğraflar mağazalara aittir. Manken, bu fotoğraflardan alınan küçük kumaş dokuları ve yaklaşık kesim çizimleriyle oluşur; sanal prova veya ölçüye göre uyum sonucu değildir.</p></div></div><button class="primary" style="margin-top:24px" data-action="close">Tamam, deneyelim ${icon('arrow')}</button></div>`);}
function feedback(o,value,reason='overall'){const fp=fingerprint(o);if(value===1&&state.feedback[fp]?.value===1){delete state.feedback[fp];toast('Bu beğeniyi geri aldık.');}else{state.feedback[fp]={value,reason,features:features(o),style:o.style,items:o.items.map(p=>p.id),date:new Date().toISOString()};toast(value>0?'Pusulaya bir iz daha. Sana yakın olanı not ettik.':'Not ettik. Sonraki denemede bu izi kullanacağız.');}persist();if(value<0)rebuild();render();}
function ownToggle(id){if(state.owned.includes(id))state.owned=state.owned.filter(x=>x!==id);else state.owned.push(id);persist();rebuild();render();}
function exportData(){const blob=new Blob([JSON.stringify({app:'Kendince',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='kendince-yedek-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('Profil, gardırop ve seçimlerin indirildi.');}
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-page]');if(n){navigate(n.dataset.page);return;}
 const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;
 if(action==='close')return closeModal();
 if(action==='mannequin'){const o=getOutfit(id);if(o)return mannequinModal(o);}
 if(action==='preview-mode'){state.preview.mode=value==='pieces'?'pieces':'mannequin';persist();return render();}
 if(action==='preview-layer'){state.preview.layerOpen=state.preview.layerOpen===false;persist();const modalOpen=$('#modal').open;render();if(modalOpen&&activeOutfit)mannequinModal(activeOutfit);return;}
 if(action==='profile')return profileModal();
 if(action==='about')return aboutModal();
 if(action==='export')return exportData();
 if(action==='generate'){state.seed++;persist();rebuild();render();return toast(outfits.length?outfits.length+' yeni başlangıç hazırladık.':'Bu beden ve bütçede yeterli parça bulunamadı.');}
 if(action==='occasion'){state.filters.occasion=value;persist();rebuild();return render();}
 if(action==='relax'){state.filters.style='all';state.profile.size='';state.profile.bottomSize='';state.profile.shoe=null;state.filters.weather='mild';if(resultMeta.cheapest>state.filters.budget)state.filters.budget=Math.ceil(resultMeta.cheapest/100)*100;persist();rebuild();return render();}
 if(action==='detail'){const o=getOutfit(id);if(o)return detailModal(o);}
 if(action==='save'){const o=getOutfit(id);if(!o)return;const fp=fingerprint(o),isSaved=state.saved.some(s=>s.fp===fp);state.saved=isSaved?state.saved.filter(s=>s.fp!==fp):[...state.saved,{fp,style:o.style,items:o.items.map(p=>p.id),date:new Date().toISOString()}];persist();render();if($('#modal').open&&activeOutfit?.id===id){if($('#modal-content').innerHTML.includes('mannequin-modal'))mannequinModal(o);else detailModal(o);}return toast(isSaved?'Kayıttan çıkarıldı.':'Tekrar bakmak için sakladık.');}
 if(action==='like'){const o=getOutfit(id);if(o){feedback(o,1);if($('#modal').open)detailModal(o);}return;}
 if(action==='dislike'){const o=getOutfit(id);if(o)return dislikeModal(o);}
 if(action==='reject'){feedback(activeOutfit,-1,value);return closeModal();}
 if(action==='back-detail')return detailModal(activeOutfit);
 if(action==='alternatives')return alternativeModal(id);
 if(action==='swap'){const p=find(id),oldfp=fingerprint(activeOutfit);activeOutfit={...activeOutfit,items:activeOutfit.items.map(x=>x.id===alternateProduct.id?p:x)};activeOutfit.fp=fingerprint(activeOutfit);activeOutfit.id=activeOutfit.fp+'::'+activeOutfit.style;activeOutfit.features=features(activeOutfit);outfits=outfits.map(o=>fingerprint(o)===oldfp?activeOutfit:o);render();detailModal(activeOutfit);return toast('Parça değişti. Hesabı yeniden yaptık.');}
 if(action==='product')return productModal(find(id));
 if(action==='custom')return addCustomModal();
 if(action==='wardrobe-tab'){wardrobeTab=value;return render();}
 if(action==='unown'){state.owned=state.owned.filter(x=>x!==id);persist();rebuild();render();return toast('Parça gardırobundan çıkarıldı.');}
 if(action==='remove-custom'){state.custom=state.custom.filter(x=>x.id!==id);state.saved=state.saved.filter(s=>!s.items.includes(id));persist();rebuild();render();return toast('Kendi parçan çıkarıldı.');}
 if(action==='own-toggle'){ownToggle(id);return toast(state.owned.includes(id)?'Gardırobuna eklendi. Kombin hesabından düşecek.':'Gardırobundan çıkarıldı.');}
 if(action==='hide'){if(!state.hidden.includes(id))state.hidden.push(id);persist();rebuild();render();closeModal();return toast('Bu ürün önerilerden gizlendi. Gardırobumdan geri alabilirsin.');}
 if(action==='unhide'){state.hidden=state.hidden.filter(x=>x!==id);persist();rebuild();render();return toast('Ürün önerilere geri eklendi.');}
 if(action==='price-note')return priceNoteModal(find(id));
 if(action==='clear-price'){delete state.priceNotes[id];persist();rebuild();render();priceNoteModal(find(id));return toast('Kaynak fiyatına geri döndük.');}
 if(action==='reset-taste')return showModal(`<div class="modal">${modalHead('Pusulaya yeni bir başlangıç.','Değerlendirmelerin temizlenecek. Kayıtlı kombinlerin ve gardırobun kalır.')}<button class="primary" data-action="confirm-reset">Değerlendirmeleri sıfırla</button><button class="outline-button" style="margin-top:12px;width:100%;justify-content:center" data-action="close">Vazgeç</button></div>`);
 if(action==='confirm-reset'){state.feedback={};persist();rebuild();render();closeModal();return toast('Pusula tekrar ortada. Yeni denemelere açık.');}
});
document.addEventListener('change',e=>{
 const t=e.target;if(t.dataset.previewBuild!==undefined){state.preview.build=['slender','broad'].includes(t.value)?t.value:'regular';persist();const modalOpen=$('#modal').open;render();if(modalOpen&&activeOutfit)mannequinModal(activeOutfit);return;}if(t.dataset.own){ownToggle(t.dataset.own);detailModal(activeOutfit);return;}
 if(t.id==='budget'){const n=Number(t.value);if(!Number.isFinite(n)||n<0||n>100000){t.value=state.filters.budget;return toast('0–100.000 TL arasında bir bütçe gir.');}state.filters.budget=n;persist();rebuild();return render();}
 if(t.id==='budget-range'){state.filters.budget=Number(t.value);persist();rebuild();return render();}
 if(t.id==='explore'){state.filters.explore=Number(t.value);persist();rebuild();return render();}
 if(['style-filter','weather'].includes(t.id)){state.filters[t.id==='style-filter'?'style':'weather']=t.value;persist();rebuild();return render();}
 if(t.id==='available-only'){state.filters.availableOnly=t.checked;persist();rebuild();return render();}
 if(['catalog-category','catalog-kind','catalog-brand','catalog-sort','catalog-stock'].includes(t.id)){catalogFilters[t.id.replace('catalog-','')]=t.value;refreshCatalogRows();}
 if(t.id==='catalog-my-size'){catalogFilters.mySize=t.checked;refreshCatalogRows();}
 if(['catalog-min','catalog-max'].includes(t.id)){catalogFilters[t.id.replace('catalog-','')]=t.value;refreshCatalogRows();}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='budget-range')$('#budget').value=t.value;if(t.id==='explore')$('#explore-value').textContent=t.value+'%';if(t.id==='catalog-search'){catalogFilters.query=t.value;refreshCatalogRows();}if(t.id==='wears'){const n=Number(t.value);$('#cost-per-wear').textContent=n>=1&&n<=1000?money(round(cost(activeOutfit,state)/n)):'—';}});
document.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,data=new FormData(form);
 if(form.id==='profile-form'){for(const k of ['age','height','weight','chest','waist','shoe'])state.profile[k]=data.get(k)?Number(data.get(k)):null;state.profile.fit=data.get('fit');state.profile.size=data.get('size');state.profile.bottomSize=String(data.get('bottomSize')||'').trim().toUpperCase();persist();rebuild();render();profileModal();toast('Ölçülerini kaydettik. Kalıp rehberin aşağıda.');}
 if(form.id==='custom-form'){const cat=data.get('category'),family=data.get('family'),fit=data.get('fit'),name=data.get('name').trim();if(!name)return toast('Parçana bir ad ver.');const p={id:'own-'+crypto.randomUUID(),name,category:cat,family,fit,fitLabel:fit==='wide'?'Rahat / bol':fit==='slim'?'Dar / slim':'Regular / düz',color:families[family],brand:'Gardırobum',kind:cat,price:0,originalPrice:0,custom:true,patterned:data.get('pattern')==='patterned',warmth:Number(data.get('warmth')),formality:Number(data.get('formality')),material:'Kendi parçan',description:'Kendi gardırobuna eklediğin parça.',sizes:[]};state.custom.push(p);persist();rebuild();render();closeModal();toast('Gardırobuna eklendi. Uygun kombinlere katılacak.');}
 if(form.id==='price-note-form'){const price=Number(data.get('price'));if(!Number.isFinite(price)||price<1||price>100000)return toast('Geçerli bir ürün fiyatı gir.');const id=form.dataset.id;state.priceNotes[id]??=[];state.priceNotes[id].push({price,date:new Date().toISOString(),source:'manual'});persist();rebuild();render();priceNoteModal(find(id));toast('Fiyat gözlemin kaydedildi. Kombin hesabı güncellendi.');}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['atelier','compass','wardrobe','prices'].includes(p)&&p!==page){page=p;render();}});
try{const r=await fetch('catalog.json?v=3',{cache:'no-store'});if(!r.ok)throw new Error('catalog');const c=await r.json();try{const t=await fetch('mannequin-textures.json?v=3',{cache:'force-cache'});if(t.ok)setTextures(await t.json());}catch{}products=c.products;catalogDate=c.checkedAt;catalogVerifiedAt=c.verifiedAt;catalogStats=c.stats||{};state.owned=state.owned.filter(id=>find(id));state.hidden=state.hidden.filter(id=>find(id));state.filters.explore=Number(state.filters.explore)||0;rebuild();const requested=location.hash.slice(1);if(['atelier','compass','wardrobe','prices'].includes(requested))page=requested;render();if(!storageOK)toast('Kalıcı kayıt kullanılamıyor. Bu oturumdaki seçimlerin kullanılacak.');}
catch(error){$('#app').innerHTML='<div class="empty" style="margin-top:50px"><h3>Atölyeyi açamadık.</h3><p>Ürün kataloğu yüklenemedi. Sayfayı yeniden açmayı deneyebilirsin.</p><button class="outline-button" onclick="location.reload()">Yeniden dene</button></div>';console.error(error);}
